// The Markdown copy of an API reference page (content/docs/developers/api,
// generated by the main app's `bun run openapi:generate`). The page's prose
// is the operation's description; its `<OpenAPIPage />` renders the operation
// itself in the browser only, so lib/agents/llm-markdown.ts drops it. This
// renders the same operation from the OpenAPI document as plain Markdown, so
// /docs/developers/api/<slug>.md, llms-full.txt and "Copy Markdown" carry the
// whole thing: method and path, auth, parameters, request body, responses and
// a curl example.

type Json = Record<string, unknown>;

/** The parts of an OpenAPI 3.1 document this module reads. */
export interface OpenApiDocument {
  servers?: { url: string }[];
  paths?: Record<string, Json>;
  components?: {
    schemas?: Record<string, Json>;
    responses?: Record<string, Json>;
    headers?: Record<string, Json>;
  };
}

export interface OpenApiOperation {
  path: string;
  /** Upper case: `GET` */
  method: string;
  operation: Json;
  /** Parameters shared by every method of the path */
  pathParameters: Json[];
}

const METHODS = ["get", "post", "put", "patch", "delete"] as const;

/** `getQrImage` → `get-qr-image`: the generator's page names (apps/app/scripts/openapi/pages.ts). */
export const operationSlug = (operationId: string) =>
  operationId.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`);

/** The operation a reference page renders, by the page's slug. */
export function findOperation(
  document: OpenApiDocument,
  slug: string,
): OpenApiOperation | null {
  for (const [path, item] of Object.entries(document.paths ?? {})) {
    for (const method of METHODS) {
      const operation = item[method] as Json | undefined;
      const id = operation?.operationId;
      if (operation && typeof id === "string" && operationSlug(id) === slug) {
        return {
          path,
          method: method.toUpperCase(),
          operation,
          pathParameters: (item.parameters as Json[] | undefined) ?? [],
        };
      }
    }
  }
  return null;
}

// ─── Schemas ─────────────────────────────────────────────────────────────────

/** Follows a local `$ref` (`#/components/schemas/X`), or returns the value. */
function deref(document: OpenApiDocument, value: unknown): Json {
  if (!value || typeof value !== "object") return {};
  const ref = (value as Json).$ref;
  if (typeof ref !== "string" || !ref.startsWith("#/")) return value as Json;
  const target = ref
    .slice(2)
    .split("/")
    .reduce<unknown>(
      (node, key) => (node as Json | undefined)?.[key],
      document as unknown,
    );
  return (target as Json | undefined) ?? {};
}

const code = (value: unknown) => `\`${String(value).replace(/`/g, "'")}\``;

/** One line of a table cell: no newlines, pipes escaped. */
const cell = (text: string) =>
  text
    .replace(/\s*\n\s*/g, " ")
    .replace(/\|/g, "\\|")
    .trim();

/** `string`, `integer`, `"a" | "b"`, `Code[]`, `string | null`, … */
function typeOf(document: OpenApiDocument, raw: unknown, depth = 0): string {
  const refName =
    raw && typeof raw === "object" && typeof (raw as Json).$ref === "string"
      ? ((raw as Json).$ref as string).split("/").at(-1)
      : undefined;
  const schema = deref(document, raw);
  if (schema.const !== undefined) return JSON.stringify(schema.const);
  if (Array.isArray(schema.enum)) {
    const values = schema.enum as unknown[];
    if (values.length > 12) {
      return `${values
        .slice(0, 6)
        .map((v) => JSON.stringify(v))
        .join(" | ")} | … (${values.length} values)`;
    }
    return values.map((v) => JSON.stringify(v)).join(" | ");
  }
  const alternatives = (schema.anyOf ?? schema.oneOf) as unknown[] | undefined;
  if (alternatives && depth < 3) {
    return [
      ...new Set(alternatives.map((a) => typeOf(document, a, depth + 1))),
    ].join(" | ");
  }
  if (Array.isArray(schema.allOf) && depth < 3) {
    return typeOf(document, (schema.allOf as unknown[])[0], depth + 1);
  }
  const types = Array.isArray(schema.type)
    ? (schema.type as string[])
    : typeof schema.type === "string"
      ? [schema.type]
      : [];
  const named = types.map((type) => {
    if (type === "array") {
      return `${typeOf(document, schema.items, depth + 1)}[]`;
    }
    if (type === "object" && refName) return refName;
    if (type === "string" && typeof schema.format === "string") {
      return `string (${schema.format})`;
    }
    return type;
  });
  if (named.length === 0) return refName ?? "any";
  return named.join(" | ");
}

/** Limits and defaults, after the type: `64–2048`, `up to 100`, `default 512`. */
function constraints(schema: Json): string {
  const parts: string[] = [];
  // zod writes JavaScript's safe-integer bounds on every integer: not a limit.
  const bound = (value: unknown) =>
    typeof value === "number" && Math.abs(value) >= Number.MAX_SAFE_INTEGER
      ? undefined
      : value;
  const min = bound(schema.minimum ?? schema.exclusiveMinimum);
  const max = bound(schema.maximum ?? schema.exclusiveMaximum);
  if (min !== undefined && max !== undefined) parts.push(`${min}–${max}`);
  else if (min !== undefined) parts.push(`at least ${min}`);
  else if (max !== undefined) parts.push(`at most ${max}`);
  if (schema.minLength !== undefined && schema.maxLength !== undefined) {
    parts.push(`${schema.minLength}–${schema.maxLength} characters`);
  } else if (schema.maxLength !== undefined) {
    parts.push(`up to ${schema.maxLength} characters`);
  }
  if (schema.minItems !== undefined || schema.maxItems !== undefined) {
    parts.push(
      `${schema.minItems ?? 0}–${schema.maxItems ?? "∞"} items`.replace(
        "–∞",
        " or more",
      ),
    );
  }
  if (schema.default !== undefined) {
    parts.push(`default ${code(JSON.stringify(schema.default))}`);
  }
  return parts.join(", ");
}

interface Row {
  name: string;
  type: string;
  required: boolean;
  description: string;
}

/** An object schema's properties as rows, nested objects flattened as `a.b`. */
function propertyRows(
  document: OpenApiDocument,
  raw: unknown,
  prefix = "",
  depth = 0,
): Row[] {
  const schema = deref(document, raw);
  if (Array.isArray(schema.allOf)) {
    return (schema.allOf as unknown[]).flatMap((part) =>
      propertyRows(document, part, prefix, depth),
    );
  }
  const alternatives = (schema.anyOf ?? schema.oneOf) as unknown[] | undefined;
  if (alternatives && !schema.properties) {
    // `X | null` and the like: the object alternative's fields.
    const object = alternatives.find(
      (a) => typeof deref(document, a).properties === "object",
    );
    return object ? propertyRows(document, object, prefix, depth) : [];
  }
  const properties = (schema.properties ?? {}) as Record<string, unknown>;
  const required = new Set((schema.required as string[] | undefined) ?? []);
  return Object.entries(properties).flatMap(([key, raw]) => {
    const property = deref(document, raw);
    const name = `${prefix}${key}`;
    const limits = constraints(property);
    const description = [
      typeof property.description === "string" ? property.description : "",
      limits,
    ]
      .filter(Boolean)
      .join(". ");
    const row: Row = {
      name,
      type: typeOf(document, raw),
      required: required.has(key),
      description,
    };
    if (depth >= 2) return [row];
    const items =
      property.type === "array" ||
      (Array.isArray(property.type) &&
        (property.type as string[]).includes("array"))
        ? deref(document, property.items)
        : null;
    if (items?.properties) {
      return [
        row,
        ...propertyRows(document, property.items, `${name}[].`, depth + 1),
      ];
    }
    if (property.properties) {
      return [row, ...propertyRows(document, raw, `${name}.`, depth + 1)];
    }
    return [row];
  });
}

function rowsTable(rows: Row[]): string {
  if (rows.length === 0) return "";
  return [
    "| Field | Type | Required | Description |",
    "| --- | --- | --- | --- |",
    ...rows.map(
      (row) =>
        `| ${code(row.name)} | ${cell(row.type)} | ${row.required ? "Yes" : "No"} | ${cell(row.description)} |`,
    ),
  ].join("\n");
}

/** A schema as Markdown: a field table for objects, one line otherwise. */
function schemaMarkdown(document: OpenApiDocument, raw: unknown): string {
  const schema = deref(document, raw);
  const alternatives = (schema.anyOf ?? schema.oneOf) as unknown[] | undefined;
  if (alternatives && !schema.properties) {
    const objects = alternatives.filter(
      (a) =>
        typeof deref(document, a).properties === "object" ||
        deref(document, a).type === "array",
    );
    if (objects.length > 1) {
      return objects
        .map((alternative) => {
          const label = typeOf(document, alternative);
          const own = deref(document, alternative);
          const text =
            typeof own.description === "string" ? `: ${own.description}` : "";
          const rows = propertyRows(
            document,
            own.type === "array" ? own.items : alternative,
          );
          return `**${label}**${text}\n\n${rowsTable(rows)}`;
        })
        .join("\n\n");
    }
  }
  const rows = propertyRows(document, raw);
  if (rows.length > 0) return rowsTable(rows);
  const type = typeOf(document, raw);
  const text =
    typeof schema.description === "string" ? `: ${schema.description}` : "";
  return `${code(type)}${text}`;
}

// ─── Operation ───────────────────────────────────────────────────────────────

const json = (value: unknown, title?: string) =>
  `\`\`\`json${title ? ` title="${title}"` : ""}\n${JSON.stringify(value, null, 2)}\n\`\`\``;

/** Every example of a media type: `example`, or each of `examples`. */
function examplesOf(media: Json): { summary?: string; value: unknown }[] {
  if (media.example !== undefined) return [{ value: media.example }];
  return Object.values((media.examples ?? {}) as Record<string, Json>).map(
    (example) => ({
      summary:
        typeof example.summary === "string" ? example.summary : undefined,
      value: example.value,
    }),
  );
}

function parametersSection(
  document: OpenApiDocument,
  title: string,
  parameters: Json[],
): string {
  if (parameters.length === 0) return "";
  const rows = parameters.map((parameter) => {
    const schema = (parameter.schema as Json | undefined) ?? {};
    const limits = constraints(schema);
    const example =
      parameter.example !== undefined
        ? `Example: ${code(String(parameter.example))}`
        : "";
    return `| ${code(parameter.name)} | ${cell(typeOf(document, schema))} | ${parameter.required ? "Yes" : "No"} | ${cell(
      [
        typeof parameter.description === "string" ? parameter.description : "",
        limits,
        example,
      ]
        .filter(Boolean)
        .join(". "),
    )} |`;
  });
  return [
    `### ${title}`,
    "",
    "| Name | Type | Required | Description |",
    "| --- | --- | --- | --- |",
    ...rows,
  ].join("\n");
}

function authLine(operation: Json): string {
  const requirements = (operation.security as Json[] | undefined) ?? [];
  if (requirements.length === 0) {
    return "**Auth:** none. No key or token is needed, and the request doesn't use a daily quota.";
  }
  const scope = requirements.flatMap((r) => (r.oauth2 as string[]) ?? [])[0];
  const optional = requirements.some((r) => Object.keys(r).length === 0);
  const scopes =
    scope === "codes:read"
      ? "`codes:read` or `codes:write`"
      : scope
        ? `\`${scope}\``
        : "";
  return `**Auth:** an API key or an OAuth 2.0 access token, sent as \`Authorization: Bearer <key or token>\`${scopes ? `, with the scope ${scopes}` : ""}${optional ? ". Optional: see the description for when a request works without one" : ""}.`;
}

/** A path with its example values filled in: `/codes/{id}` → `/codes/cm5…`. */
function examplePath(path: string, parameters: Json[]): string {
  return path.replace(/\{([^}]+)\}/g, (match, name: string) => {
    const parameter = parameters.find(
      (p) => p.name === name && p.in === "path",
    );
    return parameter?.example !== undefined ? String(parameter.example) : match;
  });
}

function curlExample(
  found: OpenApiOperation,
  parameters: Json[],
  baseUrl: string,
): string {
  const query = parameters
    .filter((p) => p.in === "query" && p.example !== undefined)
    .map(
      (p) =>
        `${encodeURIComponent(String(p.name))}=${encodeURIComponent(String(p.example))}`,
    );
  const url = `${baseUrl}${examplePath(found.path, parameters)}${query.length ? `?${query.join("&")}` : ""}`;
  const lines = [
    `curl${found.method === "GET" ? "" : ` -X ${found.method}`} "${url}"`,
  ];
  const secured =
    ((found.operation.security as Json[] | undefined) ?? []).length > 0;
  if (secured) lines.push(`  -H "Authorization: Bearer $QRDX_API_KEY"`);
  for (const header of parameters.filter(
    (p) => p.in === "header" && p.example !== undefined,
  )) {
    lines.push(`  -H "${header.name}: ${header.example}"`);
  }
  const body = found.operation.requestBody as Json | undefined;
  const media = (body?.content as Record<string, Json> | undefined)?.[
    "application/json"
  ];
  if (media) {
    const example = examplesOf(media)[0]?.value;
    lines.push(`  -H "Content-Type: application/json"`);
    if (example !== undefined) {
      lines.push(`  -d '${JSON.stringify(example).replace(/'/g, "'\\''")}'`);
    }
  }
  return `\`\`\`bash title="Terminal"\n${lines.join(" \\\n")}\n\`\`\``;
}

function responseSection(
  document: OpenApiDocument,
  status: string,
  raw: unknown,
): string {
  const response = deref(document, raw);
  const description =
    typeof response.description === "string" ? response.description : "";
  const lines = [`#### ${status}`, "", description];
  const headers = Object.keys((response.headers as Json | undefined) ?? {});
  if (headers.length > 0) {
    lines.push("", `Headers: ${headers.map(code).join(", ")}.`);
  }
  const content = (response.content ?? {}) as Record<string, Json>;
  const types = Object.keys(content);
  const isError = !status.startsWith("2");
  if (types.length > 0 && !types.includes("application/json")) {
    lines.push("", `Returns ${types.map(code).join(", ")}.`);
  }
  const media = content["application/json"];
  if (media) {
    if (!isError) {
      lines.push("", schemaMarkdown(document, media.schema));
      for (const example of examplesOf(media)) {
        lines.push("", json(example.value, example.summary));
      }
    } else {
      // Errors share one shape; the codes are in the description. One example.
      const [example] = examplesOf(media);
      if (example) lines.push("", json(example.value));
    }
  }
  return lines.join("\n");
}

/** The operation as Markdown, to follow the page's own text. */
export function operationMarkdown(
  document: OpenApiDocument,
  found: OpenApiOperation,
): string {
  const { operation, method, path } = found;
  const baseUrl =
    document.servers?.find((server) => /^https?:/.test(server.url))?.url ?? "";
  const parameters = [
    ...found.pathParameters,
    ...((operation.parameters as Json[] | undefined) ?? []),
  ].map((parameter) => deref(document, parameter));
  const byLocation = (location: string) =>
    parameters.filter((p) => p.in === location);

  const sections: string[] = [
    `## ${method} ${path}`,
    "",
    `\`${method} ${baseUrl}${path}\``,
    "",
    authLine(operation),
  ];

  for (const [location, title] of [
    ["path", "Path parameters"],
    ["query", "Query parameters"],
    ["header", "Headers"],
  ] as const) {
    const section = parametersSection(document, title, byLocation(location));
    if (section) sections.push("", section);
  }

  const body = operation.requestBody as Json | undefined;
  if (body) {
    const content = (body.content ?? {}) as Record<string, Json>;
    for (const [type, media] of Object.entries(content)) {
      const schema = deref(document, media.schema);
      sections.push(
        "",
        "### Request body",
        "",
        `${code(type)}${body.required ? ", required" : ""}${typeof schema.description === "string" ? `. ${schema.description}` : ""}`,
        "",
        schemaMarkdown(document, media.schema),
      );
      for (const example of examplesOf(media)) {
        sections.push("", json(example.value, example.summary));
      }
    }
  }

  const responses = Object.entries(
    (operation.responses ?? {}) as Record<string, unknown>,
  ).sort(([a], [b]) => Number(a) - Number(b));
  if (responses.length > 0) {
    sections.push("", "### Responses");
    for (const [status, response] of responses) {
      sections.push("", responseSection(document, status, response));
    }
  }

  sections.push("", "### Example", "", curlExample(found, parameters, baseUrl));

  return `${sections.join("\n")}\n`;
}
